package com.epam.learn.microservices.resourceservice.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * A stored MP3 file. The id is generated by the database and becomes the Resource ID
 * that the Song Service uses for the matching metadata.
 *
 * <p>{@code byte[]} without {@code @Lob} maps to PostgreSQL {@code bytea}; {@code @Lob} would map to
 * a large object ({@code oid}) with separate storage and cleanup semantics.
 */
@Entity
@Table(name = "resource")
public class Resource {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private byte[] data;

    protected Resource() {
        // required by JPA
    }

    public Resource(byte[] data) {
        this.data = data;
    }

    public Long getId() {
        return id;
    }

    public byte[] getData() {
        return data;
    }
}
